-- Bancada descartável. Nenhuma mensagem, nenhuma chamada de rede; rollback integral.
begin;
create temporary table d4 as select gen_random_uuid() shop,gen_random_uuid() person,gen_random_uuid() a,gen_random_uuid() b,gen_random_uuid() plan,gen_random_uuid() grp,gen_random_uuid() cycle,null::jsonb job,null::jsonb body,null::jsonb step;
create function pg_temp.check_d4(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select pg_temp.check_d4((select not enabled from public.whatsapp_care_cycle_policy),'Contrato novo não herda liberação do piloto anterior');
update public.whatsapp_send_controls set paused=false where scope='global';
update d4 set shop=(public.register_my_barbershop(gen_random_uuid(),'Ciclo Fictício','America/Sao_Paulo','single',true,'teste','teste','teste')->>'shop_id')::uuid;
select public.platform_create_whatsapp_channel(a,'Ciclo A') from d4;
select public.platform_create_whatsapp_channel(b,'Ciclo B') from d4;
update public.whatsapp_channels set display_phone=case id when (select a from d4) then '+5511800000111' else '+5511800000222' end,status='open' where id in(select a from d4 union all select b from d4);
select public.platform_confirm_whatsapp_control(id,routing_version,display_phone,instance_name,true) from public.whatsapp_channels where id in(select a from d4 union all select b from d4);
select public.platform_plan_whatsapp_distribution(plan,array[shop],false) from d4;
select public.platform_apply_whatsapp_distribution(plan) from d4;
-- Rota explícita da fixture: outros ensaios podem conservar números com a mesma identidade.
select public.platform_set_whatsapp_route(d.shop,null,(select version from public.whatsapp_number_links where barbershop_id=d.shop and staff_id is null and removed_at is null),d.a,d.b,null,'primary',false,false,false) from d4 d;
select pg_temp.check_d4((select jsonb_array_length(public.care_cycle_composition(shop))=2 from d4),'Composição da loja usa dois telefones físicos com controle confirmado');
insert into auth.users(id,email,raw_user_meta_data) select person,person||'@example.invalid','{}' from d4;
insert into public.memberships(user_id,barbershop_id,role) select person,shop,'customer' from d4;

create function pg_temp.denied(query text,expected text,label text) returns void language plpgsql as $$begin
 begin execute query;raise exception 'FAIL: %',label;exception when others then
 if sqlerrm like 'FAIL:%' or sqlerrm<>expected then raise;end if;raise notice 'PASS: %',label;end;
end $$;
create temporary table access_test(id uuid,job jsonb,expires_at timestamptz,cycle uuid,enrollment timestamptz);
insert into access_test values(null,null,null,null,null);
select pg_temp.check_d4((select not assisted_access_enabled from public.whatsapp_care_cycle_policy),'Acompanhamento nasce desligado sem ligar piloto');
select set_config('request.jwt.claim.sub',(select person::text from d4),true);
select pg_temp.denied(format('select public.care_access_start(%L,%L,array[%L,%L]::uuid[],true)',shop,'+5511998888777',a,b),'GROUP_UNAVAILABLE','Política desligada impede nova intenção') from d4;
update public.whatsapp_care_cycle_policy set enabled=true,assisted_access_enabled=true where singleton;
select pg_temp.denied(format('select public.care_access_start(%L,%L,array[%L,%L]::uuid[],false)',shop,'+5511998888777',a,b),'GROUP_UNAVAILABLE','Sem aceite explícito não inicia') from d4;
update public.whatsapp_channels set connection_observed_at=clock_timestamp()-interval '1 day' where id in(select a from d4 union all select b from d4);
update access_test set id=(select public.care_access_start(shop,'+5511998888777',array[a,b],true) from d4);

select pg_temp.check_d4(public.care_entry_background_queue()='[]'::jsonb,'Servidor nasce desligado');
update public.whatsapp_care_cycle_policy set background_access_enabled=true,pilot_isolation_required=true,pilot_shop_id=(select shop from d4),pilot_customer_id=(select person from d4);
select pg_temp.check_d4(jsonb_array_length(public.care_entry_background_queue())=1,'Só intenção consentida do piloto entra na fila');
select pg_temp.check_d4((public.care_entry_background_queue()->0->>'user')=(select person::text from d4),'Identidade vem da intenção, não do chamador');
update access_test set job=(select public.claim_care_access(person,shop) from d4);
select set_config('request.jwt.claim.sub','',true);
select pg_temp.denied(format('select public.resume_care_access_background(%L,%L,%L)',t.id,d.person,t.job->>'token'),'GROUP_PARTICIPANTS_CHANGED','Servidor conserva necessidade de conexão recente') from access_test t,d4 d;
select public.record_care_access_connections(t.id,d.person,(t.job->>'token')::uuid,(select jsonb_agg(n||jsonb_build_object('status','open','observed_phone',n->>'phone')) from jsonb_array_elements(t.job->'targets') n)) from access_test t,d4 d;
select pg_temp.denied(format('select public.resume_care_access_background(%L,%L,%L)',t.id,gen_random_uuid(),t.job->>'token'),'GROUP_UNAVAILABLE','Outro usuário não usa a posse do titular') from access_test t;
select pg_temp.denied(format('select public.resume_care_access_background(%L,%L,%L)',t.id,d.person,gen_random_uuid()),'GROUP_UNAVAILABLE','Posse falsa não cria grupo') from access_test t,d4 d;
update access_test t set cycle=public.resume_care_access_background(t.id,(select person from d4),(t.job->>'token')::uuid);
select pg_temp.check_d4((select cycle is not null from access_test),'Intenção autenticada é retomada sem JWT de cliente');
select pg_temp.check_d4(auth.uid() is null,'Servidor não fabrica claims de usuário');
select pg_temp.check_d4((select count(*)=1 from public.whatsapp_care_cycles where id=(select cycle from access_test)),'Uma criação durável, sem ciclo duplicado');
select pg_temp.check_d4((select public.resume_care_access_background(t.id,d.person,(t.job->>'token')::uuid)=t.cycle from access_test t,d4 d),'Reentrega preserva ciclo existente');
select pg_temp.check_d4((select whatsapp_verified_at is null and whatsapp_e164 is null from public.profiles where id=(select person from d4)),'Automação não confirma nem reescreve telefone');
select pg_temp.check_d4((select count(*)=0 from public.auth_otp_challenges where user_id=(select person from d4)),'Servidor não solicita código de login sozinho');
update public.whatsapp_care_cycles set group_jid='12345-67890@g.us' where id=(select cycle from access_test);
update public.whatsapp_care_access set next_at=clock_timestamp()+interval '1 hour';
select public.care_entry_background_wake('instancia-intrusa','12345-67890@g.us');
select pg_temp.check_d4((select next_at>clock_timestamp()+interval '30 minutes' from public.whatsapp_care_access where id=(select id from access_test)),'Evento de instância alheia não altera a agenda');
select public.care_entry_background_wake((select consented_numbers->0->>'instance' from public.whatsapp_care_cycles where id=(select cycle from access_test)),'12345-67890@g.us');
select pg_temp.check_d4((select next_at<=clock_timestamp() from public.whatsapp_care_access where id=(select id from access_test)),'Pedido autorizado antecipa conferência sem aprovar ninguém');
select pg_temp.check_d4((select whatsapp_verified_at is null from public.profiles where id=(select person from d4)),'Evento não vira confirmação do telefone');
update public.whatsapp_send_controls set paused=true where scope='global';
select pg_temp.check_d4(public.care_entry_background_queue()='[]'::jsonb,'Pausa esvazia fila mesmo com janela ativa');
select pg_temp.denied(format('select public.resume_care_access_background(%L,%L,%L)',t.id,d.person,t.job->>'token'),'GROUP_UNAVAILABLE','Pausa invalida posse antes do efeito') from access_test t,d4 d;
update public.whatsapp_send_controls set paused=false where scope='global';
update public.whatsapp_care_cycle_policy set pilot_customer_id=gen_random_uuid();
select pg_temp.check_d4(public.care_entry_background_queue()='[]'::jsonb,'Troca de cliente no escopo bloqueia intenção anterior');
update public.whatsapp_care_cycle_policy set pilot_customer_id=(select person from d4),pilot_shop_id=gen_random_uuid();
select pg_temp.check_d4(public.care_entry_background_queue()='[]'::jsonb,'Troca de loja bloqueia intenção anterior');
update public.whatsapp_care_cycle_policy set pilot_shop_id=(select shop from d4);
select public.finish_care_access(t.id,d.person,(t.job->>'token')::uuid,false) from access_test t,d4 d;
update public.whatsapp_care_access set next_at=clock_timestamp()-interval '1 second',expires_at=clock_timestamp()-interval '1 second';
select pg_temp.check_d4(public.care_entry_background_queue()='[]'::jsonb,'Janela expirada não se renova por tarefa');
update public.whatsapp_care_access set expires_at=clock_timestamp()+interval '10 minutes';
update public.profiles set whatsapp_e164='+5511998888000' where id=(select person from d4);
select pg_temp.check_d4(public.care_entry_background_queue()='[]'::jsonb,'Mudança de perfil cancela intenção anterior');
update public.profiles set whatsapp_e164=null where id=(select person from d4);
update public.whatsapp_care_cycle_policy set background_access_enabled=false;
select pg_temp.check_d4(public.care_entry_background_queue()='[]'::jsonb,'Desligar automação impede novos trabalhos');
select pg_temp.check_d4(not has_function_privilege('authenticated','public.care_entry_background_queue()','execute'),'Cliente não lê fila de identidades');
select pg_temp.check_d4(not has_function_privilege('anon','public.resume_care_access_background(uuid,uuid,uuid)','execute'),'Anônimo não retoma intenção');
select pg_temp.check_d4(not has_function_privilege('service_role','public.care_entry_begin_internal(uuid,uuid,boolean,uuid[],text)','execute'),'Serviço não inicia grupo sem wrapper de intenção');
select pg_temp.check_d4(not has_function_privilege('service_role','public.care_entry_start_internal(uuid,uuid,text,uuid[],boolean,uuid,bigint)','execute'),'Serviço não fabrica consentimento');
select pg_temp.check_d4(not has_table_privilege('authenticated','public.whatsapp_entry_progress','select'),'Progresso privado não expõe outro cliente');
rollback;
